const regionMap={
 '수성구':['전체','범어동','만촌동','수성동','황금동','중동','두산동','지산동','범물동','시지동','고산동'],
 '중구':['전체','동인동','삼덕동','성내동','남산동','대봉동'],
 '동구':['전체','신암동','신천동','효목동','불로동','봉무동','동촌동','안심동','혁신동'],
 '서구':['전체','내당동','비산동','평리동','상중이동','원대동'],
 '남구':['전체','이천동','봉덕동','대명동'],
 '북구':['전체','고성동','칠성동','침산동','산격동','복현동','태전동','구암동','동천동'],
 '달서구':['전체','성당동','두류동','감삼동','죽전동','장기동','상인동','월성동','진천동'],
 '달성군':['전체','화원읍','논공읍','다사읍','유가읍','옥포읍','현풍읍','가창면'],
 '군위군':['전체','군위읍','소보면','효령면','부계면','우보면','의흥면']
};
const districtBase={'수성구':7.21,'중구':5.46,'달서구':4.38,'북구':3.92,'동구':3.78,'남구':3.61,'서구':3.22,'달성군':3.08,'군위군':2.18};
const districtOrder=['수성구','중구','동구','서구','남구','북구','달서구','달성군','군위군'];
districtFilter.innerHTML=districtOrder.map(x=>`<option>${x}</option>`).join('');
function fillDongs(){dongFilter.innerHTML=regionMap[districtFilter.value].map(x=>`<option value="${x}">${x==='전체'?districtFilter.value+' 전체':x}</option>`).join('')}
function seed(){let s=[districtFilter.value,dongFilter.value,dateFilter.value,sizeFilter.value].join('');return [...s].reduce((a,c)=>((a*31+c.charCodeAt(0))>>>0),7)}
function factor(){let s=seed(),dong=dongFilter.selectedIndex?1+(s%15-7)/100:1,size=sizeFilter.value==='small'?.62:sizeFilter.value==='large'?1.34:1,month=+dateFilter.value.replace('-',''),time=1+(month-202401)*.00006;return dong*size*time}
function formatDate(){let [y,m]=dateFilter.value.split('-');return `${y}.${m}`}
function dynamicChart(){let type=document.querySelector('[data-target="chart"] .active').dataset.type,n=+periodFilter.value,s=seed(),base=type==='sale'?100:type==='jeonse'?99.4:99.8,pts=Array.from({length:n},(_,i)=>base+i*.22+Math.sin((i+s%9)/2)*.45+(s%7-3)*.05),labels=Array.from({length:n},(_,i)=>{let d=new Date(dateFilter.value+'-01T00:00:00');d.setMonth(d.getMonth()-(n-1-i));return `${d.getMonth()+1}월`}),w=700,h=240,p=34,x=i=>p+i*(w-p*2)/(n-1||1),y=v=>h-p-(v-97)/7*(h-p*2),path=pts.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');lineChart.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${[98,100,102,104].map(v=>`<line x1="${p}" y1="${y(v)}" x2="${w-p}" y2="${y(v)}" stroke="#e1e5e2"/><text x="2" y="${y(v)+3}" class="axis-label">${v}</text>`).join('')}<line x1="${p}" y1="${y(100)}" x2="${w-p}" y2="${y(100)}" stroke="#ef6d36" stroke-dasharray="5 5"/><path d="${path}" fill="none" stroke="#0d6b46" stroke-width="4"/>${pts.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="#fff" stroke="#0d6b46" stroke-width="3"><title>${labels[i]} ${v.toFixed(1)}</title></circle><text x="${x(i)}" y="232" text-anchor="middle" class="axis-label">${labels[i]}</text>`).join('')}</svg>`}
function dynamicRanks(){let f=factor(),place=dongFilter.value==='전체'?districtFilter.value:dongFilter.value;['dealRank','pyeongRank'].forEach(id=>{let type=document.querySelector(`[data-target="${id}"] .active`).dataset.type;document.querySelector('#'+id).innerHTML=names.map((n,i)=>{let base=(18.7-i*.82)*f*(type==='jeonse'?.55:type==='monthly'?.08:1),price=type==='monthly'?`${Math.round(base*500)}만 / ${Math.round(390-i*17)}만`:id==='pyeongRank'?`${Math.round(base*340).toLocaleString()}만원`:`${base.toFixed(1)}억원`;return `<div class="rank-item"><span class="num">${i+1}</span><div><b>${n}</b><small>${place} · 전용 ${i%3?84.9:129}㎡</small></div><strong>${price}<small>${formatDate()} 샘플</small></strong></div>`}).join('')})}
function dynamicRows(){let place=dongFilter.value==='전체'?districtFilter.value:dongFilter.value,[y,m]=dateFilter.value.split('-');dealRows.innerHTML=deals.map((r,i)=>{let copy=[...r];copy[1]=place;copy[3]=`${((12.8-i*.85)*factor()).toFixed(1)}억원`;copy[4]=`${y.slice(2)}.${m}.${String(18-i).padStart(2,'0')}`;return `<tr>${copy.map(c=>`<td>${c}</td>`).join('')}</tr>`}).join('')}
function refreshAll(){let f=factor(),place=dongFilter.value==='전체'?districtFilter.value:dongFilter.value;selectedDate.textContent=formatDate();marketTitle.textContent=place;marketEyebrow.textContent=`DAEGU · ${districtFilter.value} · ${place}`;avgPrice.textContent=(districtBase[districtFilter.value]*f).toFixed(2);avgJeonse.textContent=(districtBase[districtFilter.value]*.56*f).toFixed(2);monthlyAvg.textContent=`${Math.round(8200*f).toLocaleString()} / ${Math.round(118*f)}`;volume.textContent=Math.max(12,Math.round((198-districtFilter.selectedIndex*13)*(dongFilter.selectedIndex?.18:1))).toLocaleString();score.textContent=52+seed()%17;dynamicChart();dynamicRanks();dynamicRows();document.querySelectorAll('.panel:not(.map-panel) h2').forEach(h=>{h.parentElement.querySelector('.data-context')?.remove();let s=document.createElement('span');s.className='data-context';s.textContent=`${place} · ${formatDate()} 기준`;h.after(s)})}
districtFilter.onchange=()=>{fillDongs();refreshAll()};[dongFilter,dateFilter,sizeFilter,periodFilter].forEach(el=>el.addEventListener('change',refreshAll));document.querySelectorAll('.tabs').forEach(t=>t.addEventListener('click',()=>setTimeout(refreshAll)));resetBtn.addEventListener('click',()=>setTimeout(()=>{districtFilter.value='수성구';fillDongs();dongFilter.value='중동';dateFilter.value='2026-10';refreshAll()}));fillDongs();dongFilter.value='중동';refreshAll();
